 foreach ( $row as $key => $value ) { if ( str_starts_with( $key, 'career_' ) || in_array( $key, array( 'record_presentation','list_count_mode','orderby' ), true ) ) { $expect( (string) $value === (string) $saved[ $key ], 'Saved native query/presentation setting: ' . $key ); } }
