 $expect( $expected_ids === array_map( 'intval', $ids[1] ), 'All thirteen public jobs render in exact compound order beyond saved item count' );
 $expect( ! str_contains( $html, 'mrn-content-list-row__pagination' ) && 1 === substr_count( $html, 'data-mrn-row-spacing=' ), 'All mode has no pagination and one native spacing owner' );
 $expect( 13 === substr_count( $html, 'class="mrn-career__link"' ) && 13 === substr_count( $html, '>Review position<svg' ), 'One named title action and editable secondary CTA per job' );
