 $expect( 5 === substr_count( $html, 'class="mrn-career__tag"' ) && str_contains( $html, '&lt;em&gt;Literal tag&lt;/em&gt;' ), 'All five ordered repeated field tags render escaped without loss' );
 $fallback = mrn_base_stack_render_career_list_item( get_post( $owned[1] ), array( 'link_items' => 1 ) ); $expect( str_contains( $fallback, 'href="' . esc_url( get_permalink( $owned[1] ) ) . '"' ), 'Unset application URL falls back to the exact record permalink' );
 update_field( 'field_mrn_career_qa_apply', array( 'url' => 'javascript:alert(1)', 'target' => '" onload="bad', 'title' => '' ), $first ); $safe = mrn_base_stack_render_career_list_item( get_post( $first ), array( 'link_items' => 1 ) ); $expect( ! str_contains( $safe, 'javascript:' ) && ! str_contains( $safe, 'onload' ) && str_contains( $safe, esc_url( get_permalink( $first ) ) ), 'Unsafe application destinations and targets cannot reach markup' );
 $expect( '' === mrn_base_stack_render_career_list_item( get_post( $owned[13] ), array() ) && '' === mrn_base_stack_render_career_list_item( get_post( $owned[14] ), array() ), 'Draft and password-protected metadata never render as career items' );
